import type { StructuredDescriptionContentRenderer } from "../../../model/innertube.gen";
import { RendererList } from "../../../renderers/Renderer";
import styles from "./StructuredDescription.module.css";

/** Items that only the description panel shows, not the expanded inline description. */
const PANEL_ONLY_ITEMS = new Set(["videoDescriptionHeaderRenderer", "expandableVideoDescriptionBodyRenderer"]);

export interface StructuredDescriptionProps {
  data: StructuredDescriptionContentRenderer;
  /** In the description box below the player, which shows the title and text itself. */
  inline?: boolean;
}

/** The full description: header, text, chapters, transcript and links. */
export function StructuredDescription({ data, inline }: StructuredDescriptionProps) {
  const items = (data.items ?? []) as object[];
  const shown = inline ? items.filter((item) => !PANEL_ONLY_ITEMS.has(Object.keys(item)[0])) : items;
  return (
    <div className={inline ? styles.inline : styles.description}>
      <div className={styles.items}>
        <RendererList items={shown} />
      </div>
    </div>
  );
}
