import { useRef } from "react";
import type { ButtonRenderer as ButtonData, CommentRepliesRenderer } from "../../model/innertube.gen";
import { useImpression } from "../../logging/impressions";
import { ButtonRenderer } from "../../components/button/ButtonRenderer";
import { ImgShadow } from "../../components/image/Image";
import { Spinner } from "../../components/spinner/Spinner";
import styles from "./CommentReplies.module.css";

export interface CommentRepliesProps {
  data: CommentRepliesRenderer;
  expanded: boolean;
  onExpandedChange: (expanded: boolean) => void;
}

/**
 * The replies of a thread: collapsed, a "N replies" button on a branch of
 * the thread line; expanded, the replies, which load when they are shown.
 */
export function CommentReplies({ data, expanded, onExpandedChange }: CommentRepliesProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  // The replies button of a sub-thread is a tonal pill, whatever style the data names.
  const viewRepliesData = data.viewReplies?.buttonRenderer as ButtonData | undefined;
  const viewReplies = viewRepliesData && { ...viewRepliesData, style: "STYLE_DEFAULT" as const };
  const hideReplies = data.hideReplies?.buttonRenderer as ButtonData | undefined;
  const creatorThumbnail = data.viewRepliesCreatorThumbnail;
  return (
    <div ref={ref} className={styles.replies}>
      {!expanded ? (
        <div className={styles.subThread}>
          <div className={styles.threadline}>
            <div className={styles.connection} />
          </div>
          <div className={styles.subThreadContent}>
            <div className={styles.showReplies}>
              {creatorThumbnail && (
                <div className={styles.creatorThumbnail}>
                  <ImgShadow image={creatorThumbnail} width={24} />
                </div>
              )}
              {viewReplies && <ButtonRenderer data={viewReplies} expanded={false} onClick={() => onExpandedChange(true)} />}
            </div>
          </div>
        </div>
      ) : (
        <div className={styles.expandedThreads}>
          <div className={styles.hideReplies}>{hideReplies && <ButtonRenderer data={hideReplies} expanded onClick={() => onExpandedChange(false)} />}</div>
          <div className={styles.loading}>
            <Spinner size={24} />
          </div>
        </div>
      )}
    </div>
  );
}
