import { useRef } from "react";
import type {
  AdsEngagementPanelContentRenderer,
  EngagementPanelSectionListRenderer,
  MacroMarkersListRenderer,
  SectionListRenderer,
  StructuredDescriptionContentRenderer,
} from "../../../model/innertube.gen";
import { useImpression } from "../../../logging/impressions";
import { RendererList } from "../../../renderers/Renderer";
import { Spinner } from "../../../components/spinner/Spinner";
import { StructuredDescription } from "../description/StructuredDescription";
import styles from "./PanelContent.module.css";

const COMMENTS_PANEL = "engagement-panel-comments-section";

/** A spinner while a panel's content loads. */
export function ContentLoading() {
  return (
    <div className={styles.loading}>
      <Spinner />
    </div>
  );
}

function MacroMarkersList({ data }: { data: MacroMarkersListRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.markers}>
      <div className={styles.markerContents}>
        <RendererList items={data.contents as object[]} />
      </div>
    </div>
  );
}

function PanelSectionList({ data }: { data: SectionListRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const sections = ((data as { contents?: Array<{ itemSectionRenderer?: { contents?: object[]; trackingParams?: string } }> }).contents ?? []).flatMap((s) =>
    s.itemSectionRenderer ? [s.itemSectionRenderer] : [],
  );
  return (
    <div ref={ref} className={styles.sectionList}>
      {sections.map((section, i) => (
        <div key={section.trackingParams ?? i} className={styles.section}>
          {section.contents?.some((c) => "continuationItemRenderer" in c) ? <ContentLoading /> : <RendererList items={section.contents} />}
        </div>
      ))}
    </div>
  );
}

function AdsPanelContent({ data }: { data: AdsEngagementPanelContentRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.ads}>
      <div className={styles.adsContent} />
    </div>
  );
}

/**
 * The content of an engagement panel. The comments panel waits for the
 * comment section's first load, so it shows a spinner, as does a panel
 * that loads its content when it opens (the transcript).
 */
export function PanelContent({ panel }: { panel: EngagementPanelSectionListRenderer }) {
  const content = panel.content as
    | {
        sectionListRenderer?: SectionListRenderer;
        macroMarkersListRenderer?: MacroMarkersListRenderer;
        structuredDescriptionContentRenderer?: StructuredDescriptionContentRenderer;
        adsEngagementPanelContentRenderer?: AdsEngagementPanelContentRenderer;
        continuationItemRenderer?: object;
      }
    | undefined;
  if (!content) return null;
  if (panel.panelIdentifier === COMMENTS_PANEL || content.continuationItemRenderer) return <ContentLoading />;
  if (content.sectionListRenderer) return <PanelSectionList data={content.sectionListRenderer} />;
  if (content.macroMarkersListRenderer) return <MacroMarkersList data={content.macroMarkersListRenderer} />;
  if (content.structuredDescriptionContentRenderer) return <StructuredDescription data={content.structuredDescriptionContentRenderer} />;
  if (content.adsEngagementPanelContentRenderer) return <AdsPanelContent data={content.adsEngagementPanelContentRenderer} />;
  return null;
}
