import { useLayoutEffect, useRef, useState, type CSSProperties } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { StructuredDescriptionContentRenderer } from "../../../model/innertube.gen";
import { getText, type AttributedText, type FormattedText } from "../../../model/text";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { AttributedString } from "../../../components/text/AttributedString";
import { StructuredDescription } from "../description/StructuredDescription";
import styles from "./TextInlineExpander.module.css";

const messages = defineMessages({
  more: { id: "description.more", defaultMessage: "...more" },
  less: { id: "description.less", defaultMessage: "Show less" },
});

const SNIPPET_MAX_LENGTH = 400;

/**
 * The collapsed description: up to the first blank line, at most 400
 * characters, with the style and command runs that end within it.
 */
export function snippetOf(text: AttributedText | null | undefined): AttributedText | null {
  if (!text || typeof text.content !== "string") return null;
  let end = text.content.indexOf("\n\n");
  if (end < 0 || end > SNIPPET_MAX_LENGTH) end = Math.min(SNIPPET_MAX_LENGTH, text.content.length);
  const within = <T extends { startIndex?: number; length?: number }>(runs: T[] | undefined) =>
    (runs ?? []).filter((r) => (r.startIndex ?? 0) + (r.length ?? 0) <= end);
  return { content: text.content.slice(0, end), commandRuns: within(text.commandRuns), styleRuns: within(text.styleRuns) };
}

function isTruncated(snippet: HTMLElement): boolean {
  return snippet.scrollHeight > snippet.clientHeight + 1;
}

export interface TextInlineExpanderProps {
  text: AttributedText | null | undefined;
  collapsedLines?: number;
  /** The structured description that the expanded text ends with. */
  description: StructuredDescriptionContentRenderer | null;
  expanded: boolean;
  onExpandedChange: (expanded: boolean) => void;
  moreText?: FormattedText;
  lessText?: FormattedText;
}

/**
 * A description that shows a few lines and a "more" button when they
 * overflow, and the full text with the structured description when expanded.
 */
export function TextInlineExpander({ text, collapsedLines = 3, description, expanded, onExpandedChange, moreText, lessText }: TextInlineExpanderProps) {
  const intl = useIntl();
  const snippetRef = useRef<HTMLDivElement>(null);
  const [truncated, setTruncated] = useState(false);
  const snippet = snippetOf(text);
  const updateTruncation = () => {
    const el = snippetRef.current;
    if (el && !expanded) setTruncated(isTruncated(el));
  };
  useResizeObserver(snippetRef, updateTruncation);
  // Collapsing shows the snippet again; measure it before that frame paints.
  useLayoutEffect(() => {
    const el = snippetRef.current;
    if (el && !expanded) setTruncated(isTruncated(el));
  }, [expanded]);
  return (
    <div className={styles.expander}>
      {expanded && (
        <div className={styles.expanded}>
          <AttributedString text={text} />
        </div>
      )}
      <div ref={snippetRef} className={styles.snippet} hidden={expanded} style={{ "--yt-inline-expander-lines": collapsedLines } as CSSProperties}>
        <span className={styles.snippetText}>
          <AttributedString text={snippet} />
        </span>
      </div>
      {!expanded && truncated && (
        <button
          type="button"
          className={styles.toggle}
          aria-expanded={false}
          onClick={(e) => {
            e.stopPropagation();
            onExpandedChange(true);
          }}
        >
          {getText(moreText) || intl.formatMessage(messages.more)}
        </button>
      )}
      {expanded && description && <StructuredDescription data={description} inline />}
      {expanded && (
        <button
          type="button"
          className={styles.toggle}
          aria-expanded
          onClick={(e) => {
            e.stopPropagation();
            onExpandedChange(false);
          }}
        >
          {getText(lessText) || intl.formatMessage(messages.less)}
        </button>
      )}
    </div>
  );
}
