import { useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { useLocation, useMatch, useSearchParams } from "react-router";
import type { Endpoint } from "../../model/endpoints";
import { useNavigateFinishEvent } from "../../workload/stepEvents";
import { useNavigationFinished, useNavigationTelemetry } from "../../hooks/useNavigationTelemetry";
import { usePageTitle } from "../../hooks/usePageTitle";
import { watchQueryOptions } from "./queries";
import { WatchFlexy } from "./WatchFlexy";
import "./renderers";

interface Video {
  id: string;
  endpoint: Endpoint | undefined;
}

/**
 * The watch page, one instance per video. While another page is shown,
 * this one stays mounted but hidden (PageStack) and keeps its video.
 */
export default function WatchPage() {
  const [params] = useSearchParams();
  const location = useLocation();
  const active = useMatch("/watch") !== null;
  const videoId = params.get("v") ?? "";
  const endpoint = (location.state as { endpoint?: Endpoint } | null)?.endpoint;
  const [video, setVideo] = useState<Video>({ id: videoId, endpoint });
  if (active && videoId !== video.id) setVideo({ id: videoId, endpoint });
  return <Watch key={video.id} videoId={video.id} endpoint={video.endpoint} />;
}

function Watch({ videoId, endpoint }: { videoId: string; endpoint: Endpoint | undefined }) {
  useNavigationTelemetry("watch", "watch");
  const watch = useQuery(watchQueryOptions(videoId, endpoint));
  const page = watch.data;
  useNavigationFinished(page !== undefined);
  usePageTitle(page?.title);
  useNavigateFinishEvent(page);
  return <WatchFlexy page={page} />;
}
