import { useRef } from "react";
import type { ButtonRenderer as ButtonData, ChipBarViewModel, EngagementPanelTitleHeaderRenderer, MenuRenderer, SortFilterSubMenuRenderer } from "../../../model/innertube.gen";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { FormattedString } from "../../../components/text/FormattedString";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";
import { Menu } from "../../../components/menu/Menu";
import { SortFilterSubMenu } from "../../../components/menu/SortFilterSubMenu";
import { ChipBar } from "../../../components/chip/ChipBar";
import styles from "./PanelTitleHeader.module.css";

export interface PanelTitleHeaderProps {
  data: EngagementPanelTitleHeaderRenderer;
  onClose: () => void;
}

/** A panel's title row: title, contextual info, menu and the close button. */
export function PanelTitleHeader({ data, onClose }: PanelTitleHeaderProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const menu = data.menu as { menuRenderer?: MenuRenderer; sortFilterSubMenuRenderer?: SortFilterSubMenuRenderer } | undefined;
  const close = data.visibilityButton?.buttonRenderer as ButtonData | undefined;
  const chips = (data.subheader as { chipBarViewModel?: ChipBarViewModel } | undefined)?.chipBarViewModel;
  return (
    <div ref={ref} className={styles.titleHeader}>
      <div className={styles.header}>
        <div className={styles.titleContainer}>
          <h2 className={styles.title}>
            <FormattedString text={data.title as FormattedText} />
          </h2>
          {data.contextualInfo && <FormattedString text={data.contextualInfo as FormattedText} className={styles.contextualInfo} />}
        </div>
        <div className={styles.menu}>
          {menu?.menuRenderer && <Menu data={menu.menuRenderer} />}
          {menu?.sortFilterSubMenuRenderer && <SortFilterSubMenu data={menu.sortFilterSubMenuRenderer} />}
        </div>
        <div className={styles.visibilityButton}>{close && <ButtonRenderer data={close} onClick={onClose} />}</div>
      </div>
      {chips && (
        <div className={styles.subheader}>
          <ChipBar data={chips} className={styles.chipBar} />
        </div>
      )}
    </div>
  );
}
