import { useRef } from "react";
import type { CommentSimpleboxRenderer } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { getText, type FormattedText } from "../../model/text";
import { useImpression, logClick } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { ImgShadow } from "../../components/image/Image";
import styles from "./CommentSimplebox.module.css";

/**
 * The closed comment box: the user's avatar and a placeholder. Signed out,
 * opening it asks the user to sign in.
 */
export function CommentSimplebox({ data }: { data: CommentSimpleboxRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  return (
    <div ref={ref} className={styles.simplebox}>
      <ImgShadow image={data.authorThumbnail} width={40} className={styles.avatar} />
      <div className={styles.placeholderArea}>
        <button
          type="button"
          className={styles.placeholder}
          onClick={() => {
            logClick(data);
            runCommand(data.prepareAccountEndpoint as unknown as Endpoint);
          }}
        >
          {getText(data.placeholderText as FormattedText)}
        </button>
      </div>
    </div>
  );
}
