import { useRef } from "react";
import type { SubscribeButtonRenderer } from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import { getText, accessibilityLabel, type FormattedText } from "../../../model/text";
import { useEntity } from "../../../state/entities";
import { useImpression, logClick } from "../../../logging/impressions";
import { useRunCommand } from "../../../commands/useRunCommand";
import { ButtonShape } from "../../../components/button/ButtonShape";
import styles from "./SubscribeButton.module.css";

interface SubscriptionState {
  subscribed?: boolean;
}

/**
 * The subscribe button. The subscription state comes from the entity store
 * when the response has the channel's entity, so every subscribe button of
 * the channel agrees. Signed out, a click asks the user to sign in.
 */
export function SubscribeButton({ data }: { data: SubscribeButtonRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const entity = useEntity<SubscriptionState>(data.subscribedEntityKey);
  const subscribed = entity?.subscribed ?? data.subscribed;
  const text = getText((subscribed ? data.subscribedButtonText : data.unsubscribedButtonText) as FormattedText) || getText(data.buttonText as FormattedText);
  const label = accessibilityLabel(subscribed ? data.unsubscribeAccessibility : data.subscribeAccessibility);
  return (
    <div ref={ref} className={styles.host} data-subscribed={subscribed || undefined}>
      <div className={styles.animation}>
        <ButtonShape
          text={text}
          buttonStyle={subscribed ? "tonal" : "filled"}
          label={label || undefined}
          pressed={subscribed}
          onClick={() => {
            logClick(data);
            runCommand((data.signInEndpoint ?? data.onSubscribeEndpoints?.[0]) as Endpoint | undefined);
          }}
        />
      </div>
    </div>
  );
}
