import type { PlayerLegacyDesktopWatchAdsRenderer } from "../../../model/innertube.gen";
import styles from "./PlayerAds.module.css";

/**
 * The companion ad slot above the related list. The ads that would fill
 * it are served by the ad network, which the workload doesn't simulate.
 */
export function PlayerAds({ ads }: { ads: PlayerLegacyDesktopWatchAdsRenderer[] }) {
  return (
    <div className={styles.playerAds}>
      {ads.map((ad, i) => (
        <div key={i} className={styles.companion} data-show-companion={ad.showCompanion || undefined} />
      ))}
    </div>
  );
}
