import { useId, useRef } from "react";
import { Link } from "react-router";
import { defineMessages, useIntl } from "react-intl";
import type { CommentViewModel as CommentViewModelData } from "../../model/innertube.gen";
import type { CommentEntity, CommentSharedEntity, CommentSurfaceEntity, ToolbarSurfaceEntity } from "../../model/comments";
import { useEntity } from "../../state/entities";
import { useImpression, logClick } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { useUiStore } from "../../state/ui";
import { EndpointLink } from "../../components/text/EndpointLink";
import { ImgShadow } from "../../components/image/Image";
import { Icon } from "../../components/icon/Icon";
import { IconButton } from "../../components/button/IconButton";
import { CommentExpander } from "./CommentExpander";
import { CommentEngagementBar } from "./CommentEngagementBar";
import styles from "./CommentViewModel.module.css";

const messages = defineMessages({
  verified: { id: "comment.badge.verified", defaultMessage: "Verified" },
  creator: { id: "comment.badge.creator", defaultMessage: "Creator" },
  actions: { id: "comment.actions", defaultMessage: "Action menu" },
  report: { id: "comment.report", defaultMessage: "Report" },
});

export interface CommentViewModelProps {
  data: CommentViewModelData;
  videoId: string;
  isReply?: boolean;
  /** Draws the line from the avatar down to the replies. */
  hasThreadline?: boolean;
}

/**
 * A comment. Its view model only holds entity keys; the author, text,
 * counts and commands are entities from the response's framework updates.
 */
export function CommentViewModel({ data, videoId, isReply = false, hasThreadline = false }: CommentViewModelProps) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const popupOwner = useId();
  const popupOpen = useUiStore((s) => s.popup?.kind === "menu" && s.popup.owner === popupOwner);
  const openPopup = useUiStore((s) => s.openPopup);
  const comment = useEntity<CommentEntity>(data.commentKey);
  const surface = useEntity<CommentSurfaceEntity>(data.commentSurfaceKey);
  const shared = useEntity<CommentSharedEntity>(data.sharedKey);
  const toolbarSurface = useEntity<ToolbarSurfaceEntity>(data.toolbarSurfaceKey);
  if (!comment) return null;
  const author = comment.author ?? {};
  const props = comment.properties ?? {};
  const channelCommand = author.channelCommand?.innertubeCommand;
  const avatarSources = surface?.avatar?.avatarViewModel?.image?.sources;
  const avatar = avatarSources?.length ? avatarSources : author.avatarThumbnailUrl ? [{ url: author.avatarThumbnailUrl, width: 88, height: 88 }] : undefined;
  const publishedTimeCommand = surface?.publishedTimeCommand?.innertubeCommand;
  const menuLabel = shared?.toolbarShared?.menuButtonA11y || intl.formatMessage(messages.actions);
  return (
    <div ref={ref} className={isReply ? styles.reply : styles.comment}>
      <div className={styles.body}>
        <div className={styles.authorThumbnail}>
          {/* The author's name is the accessible link to the channel. */}
          <EndpointLink endpoint={channelCommand} tabIndex={-1} aria-hidden="true" className={styles.authorButton}>
            <ImgShadow image={avatar} width={isReply ? 24 : 40} />
          </EndpointLink>
          {hasThreadline && <div className={styles.threadline} />}
        </div>
        <div className={styles.main}>
          <div className={styles.header}>
            <div className={styles.headerAuthor}>
              <h3 className={styles.author}>
                <EndpointLink endpoint={channelCommand} className={styles.authorText}>
                  <span>{author.displayName}</span>
                </EndpointLink>
              </h3>
              {author.isVerified && <Icon icon="CHECK_CIRCLE_THICK" size={14} label={intl.formatMessage(messages.verified)} className={styles.badge} />}
              {author.isCreator && <span className={styles.creatorBadge}>{intl.formatMessage(messages.creator)}</span>}
              <span className={styles.publishedTime}>
                {/* The link to the comment opens the command's dialog instead of navigating. */}
                <Link
                  to={`/watch?v=${videoId}&lc=${data.commentId ?? ""}`}
                  onClick={(e) => {
                    e.preventDefault();
                    logClick(comment.loggingDirectives);
                    runCommand(publishedTimeCommand);
                  }}
                >
                  {props.publishedTime}
                </Link>
              </span>
            </div>
          </div>
          <CommentExpander
            text={props.content}
            chip={comment.pdgCommentChip?.chipText?.simpleText}
            expandText={shared?.strings?.expandText}
            collapseText={shared?.strings?.collapseText}
          />
          <CommentEngagementBar comment={comment} shared={shared} toolbarStateKey={data.toolbarStateKey} surface={toolbarSurface} isReply={isReply} />
        </div>
        <div className={styles.actionMenu}>
          <IconButton
            icon="MORE_VERT"
            label={menuLabel}
            hasPopup
            expanded={popupOpen}
            className={styles.actionButton}
            onClick={(e) =>
              openPopup(
                {
                  kind: "menu",
                  label: menuLabel,
                  anchor: e.currentTarget.getBoundingClientRect(),
                  items: [{ text: intl.formatMessage(messages.report), icon: "FLAG", command: toolbarSurface?.prepareAccountCommand?.innertubeCommand }],
                  owner: popupOwner,
                },
                e.currentTarget,
              )
            }
          />
        </div>
      </div>
    </div>
  );
}
