import { Activity, useId, useLayoutEffect, useRef } from "react";
import type { EngagementPanelSectionListRenderer, EngagementPanelTitleHeaderRenderer } from "../../../model/innertube.gen";
import { getText, type FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { useUiStore, type PanelState } from "../../../state/ui";
import { PanelTitleHeader } from "./PanelTitleHeader";
import { PanelContent } from "./PanelContent";
import styles from "./EngagementPanels.module.css";

const EXPANDED = "ENGAGEMENT_PANEL_VISIBILITY_EXPANDED";

function panelId(panel: EngagementPanelSectionListRenderer, index: number): string {
  return panel.panelIdentifier ?? panel.targetId ?? `panel-${index}`;
}

const NONE: PanelState["visible"] = {};

/** Whether a panel shows: as a command last set it, else as the response says. */
function isVisible(panel: EngagementPanelSectionListRenderer, visible: PanelState["visible"]): boolean {
  return visible[panel.panelIdentifier ?? ""] ?? visible[panel.targetId ?? ""] ?? panel.visibility === EXPANDED;
}

function EngagementPanel({ data, onClose }: { data: EngagementPanelSectionListRenderer; onClose: () => void }) {
  const ref = useRef<HTMLElement>(null);
  useImpression(ref, data);
  const header = data.header?.engagementPanelTitleHeaderRenderer as EngagementPanelTitleHeaderRenderer | undefined;
  return (
    <section ref={ref} className={styles.panel} aria-label={getText(header?.title as FormattedText | undefined) || undefined} data-target-id={data.targetId ?? data.panelIdentifier}>
      <div className={styles.header}>{header && <PanelTitleHeader data={header} onClose={onClose} />}</div>
      <div className={styles.content}>
        <PanelContent panel={data} />
      </div>
      <div className={styles.footer} />
    </section>
  );
}

/**
 * The engagement panels beside the player (description, chapters,
 * transcript, comments). Commands show and hide them through the panel
 * state, which this page claims while it is shown. Hidden panels are
 * rendered in the background, so that a panel opens at once.
 */
export function EngagementPanels({ panels }: { panels: EngagementPanelSectionListRenderer[] }) {
  const owner = useId();
  const visible = useUiStore((s) => (s.panels.owner === owner ? s.panels.visible : NONE));
  const claimPanels = useUiStore((s) => s.claimPanels);
  const releasePanels = useUiStore((s) => s.releasePanels);
  const setPanelVisible = useUiStore((s) => s.setPanelVisible);
  useLayoutEffect(() => {
    claimPanels(owner);
    return () => releasePanels(owner);
  }, [owner, claimPanels, releasePanels]);
  return (
    <div className={styles.panels}>
      {panels.map((panel, i) => {
        const id = panelId(panel, i);
        return (
          <Activity key={id} mode={isVisible(panel, visible) ? "visible" : "hidden"}>
            <EngagementPanel data={panel} onClose={() => setPanelVisible(id, false)} />
          </Activity>
        );
      })}
    </div>
  );
}
