import clsx from "clsx";
import { useInfiniteQuery } from "@tanstack/react-query";
import { useDeferredValue, useRef } from "react";
import type { ItemSectionRenderer, LockupViewModel as LockupData } from "../../../model/innertube.gen";
import type { RelatedItem, RelatedPage } from "../../../model/watch";
import { rendererKey } from "../../../renderers/registry";
import { Renderer } from "../../../renderers/Renderer";
import { useListStepEvents } from "../../../workload/stepEvents";
import { useImpression } from "../../../logging/impressions";
import { LockupViewModel } from "../../../components/lockup/LockupViewModel";
import { ContinuationItem } from "../../../components/continuation/ContinuationItem";
import { relatedQueryOptions } from "../queries";
import styles from "./RelatedList.module.css";

/** Items rendered in the first commit of a new watch page. */
const FIRST_BATCH = 4;
/** The one-column layout shows the related videos as a grid of this many, without continuation. */
const ONE_COLUMN_LIMIT = 9;

export interface RelatedListProps {
  videoId: string;
  section: ItemSectionRenderer | null;
  first: RelatedPage;
  oneColumn: boolean;
}

function RelatedListItem({ item }: { item: RelatedItem }) {
  if (item.lockupViewModel) {
    return <LockupViewModel data={item.lockupViewModel as LockupData} imageWidth="var(--yt-watch-compact-thumbnail-width)" className={styles.lockup} />;
  }
  return <Renderer data={item} />;
}

/**
 * The related videos beside the player. The first few render with the
 * page and the rest right after; more load when the end comes into view.
 */
export function RelatedList({ videoId, section, first, oneColumn }: RelatedListProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, section);
  const related = useInfiniteQuery(relatedQueryOptions(videoId, first));
  const pages = related.data.pages;
  // The first commit of a new list shows its first batch; the background
  // render, and every render after it, shows all pages.
  const shownPages = useDeferredValue(pages, null);
  const items = (shownPages ?? pages).flatMap((page) => page.items);
  const shown = shownPages ? items : items.slice(0, FIRST_BATCH);
  const continuation = pages.at(-1)?.continuation;

  useListStepEvents(related.data, "watch-next-feed");

  const loadMore = () => {
    if (related.hasNextPage && !related.isFetchingNextPage) void related.fetchNextPage();
  };
  const list = oneColumn ? shown.slice(0, ONE_COLUMN_LIMIT) : shown;
  return (
    <div className={clsx(styles.results, oneColumn && styles.grid)} data-renderer="watchNextSecondaryResultsRenderer">
      <div className={styles.items}>
        <div ref={ref} className={styles.section} data-renderer="itemSectionRenderer">
          <div className={styles.contents}>
            {list.map((item, i) => (
              <RelatedListItem key={rendererKey(item, i)} item={item} />
            ))}
            {!oneColumn && continuation && <ContinuationItem key={pages.length} data={continuation} onVisible={loadMore} />}
          </div>
        </div>
      </div>
    </div>
  );
}
