import { keepPreviousData, useInfiniteQuery } from "@tanstack/react-query";
import { useDeferredValue, useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { CommentsHeaderRenderer, ContinuationItemRenderer, ItemSectionRenderer } from "../../model/innertube.gen";
import { COMMENTS_TARGET } from "../../model/comments";
import type { Endpoint } from "../../model/endpoints";
import { useListStepEvents } from "../../workload/stepEvents";
import { useImpression } from "../../logging/impressions";
import { ContinuationItem } from "../../components/continuation/ContinuationItem";
import { RetryMessage } from "../../components/feedback/RetryMessage";
import { commandParam, continuationParam, type PageParam } from "../../api/requests";
import { commentsQueryOptions } from "./queries";
import { CommentsHeader } from "./CommentsHeader";
import { CommentThread } from "./CommentThread";
import { GhostComments } from "./GhostComments";
import styles from "./CommentsSection.module.css";

const messages = defineMessages({
  error: { id: "comments.error", defaultMessage: "Comments could not be loaded." },
});

export interface CommentsSectionProps {
  videoId: string;
  /** The section in the watch response: a continuation item that loads the comments. */
  section: ItemSectionRenderer;
}

/**
 * The comment section below the video. It loads when it comes into view:
 * the first load brings the header and the first threads, later loads
 * append threads. Choosing another sort order reloads it. Comments loaded
 * before for the same video and sort order show from the cache at once.
 */
export function CommentsSection({ videoId, section }: CommentsSectionProps) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, section);
  const initial = (section.contents as Array<{ continuationItemRenderer?: ContinuationItemRenderer }>).find((c) => c.continuationItemRenderer)?.continuationItemRenderer;
  const [sort, setSort] = useState<PageParam | undefined>(undefined);
  const [requested, setRequested] = useState(false);
  const start = sort ?? continuationParam(initial);
  // Another sort order keeps the current threads, header and sort menu
  // until its first page arrives.
  const comments = useInfiniteQuery({ ...commentsQueryOptions(videoId, start), enabled: requested, placeholderData: keepPreviousData });
  const pages = useDeferredValue(comments.data?.pages);
  const header: CommentsHeaderRenderer | null = pages?.[0]?.header ?? null;
  const threads = pages?.flatMap((page) => page.threads) ?? [];
  const continuation = pages ? pages.at(-1)?.continuation : initial;

  useListStepEvents(comments.isPlaceholderData ? undefined : comments.data, COMMENTS_TARGET, start?.token ?? null);

  const loadMore = () => {
    if (comments.hasNextPage && !comments.isFetchingNextPage) void comments.fetchNextPage();
    else if (!comments.data) setRequested(true);
  };
  const retry = () => {
    if (comments.isFetchNextPageError) void comments.fetchNextPage();
    else void comments.refetch();
  };
  const changeSort = (command: Endpoint) => {
    setSort(commandParam(command));
    setRequested(true);
  };
  return (
    <div ref={ref} id="comments" className={styles.comments} data-target-id={COMMENTS_TARGET}>
      <div className={styles.section} data-renderer="itemSectionRenderer" aria-busy={comments.isFetching}>
        <div className={styles.header}>{header && <CommentsHeader data={header} onSort={changeSort} />}</div>
        <div className={styles.contents}>
          {threads.map((thread, i) => (
            <CommentThread key={thread.commentViewModel.commentViewModel?.commentId ?? i} data={thread} videoId={videoId} />
          ))}
          {comments.isError ? (
            <RetryMessage text={intl.formatMessage(messages.error)} onRetry={retry} />
          ) : continuation && !comments.isPlaceholderData && (
            <ContinuationItem
              key={pages?.length ?? 0}
              data={continuation}
              onVisible={loadMore}
              className={styles.continuation}
              placeholder={<GhostComments />}
            />
          )}
        </div>
      </div>
    </div>
  );
}
