import clsx from "clsx";
import { useRef, useState } from "react";
import type { MenuRenderer, MetadataRowContainerRenderer, SubscribeButtonRenderer, VideoOwnerRenderer } from "../../../model/innertube.gen";
import type { WatchPage } from "../../../model/watch";
import type { AttributedText, FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { FormattedString } from "../../../components/text/FormattedString";
import { TouchFeedback } from "../../../components/feedback/TouchFeedback";
import { Menu } from "../../../components/menu/Menu";
import { VideoOwner } from "./VideoOwner";
import { SubscribeButton } from "./SubscribeButton";
import { WatchInfoText } from "./WatchInfoText";
import { TextInlineExpander } from "./TextInlineExpander";
import { MetadataRowContainer } from "./MetadataRowContainer";
import styles from "./WatchMetadata.module.css";

/**
 * Everything between the player and the comments: the title, the owner
 * with the subscribe button, the actions, and the description box.
 */
export function WatchMetadata({ page }: { page: WatchPage }) {
  const { primaryInfo, secondaryInfo } = page;
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, secondaryInfo);
  const rowRef = useRef<HTMLDivElement>(null);
  const ownerRef = useRef<HTMLDivElement>(null);
  const actionsRef = useRef<HTMLDivElement>(null);
  const [compactActions, setCompactActions] = useState(false);
  const fullActionsWidth = useRef(0);
  const [expanded, setExpanded] = useState(!!secondaryInfo?.defaultExpanded);
  // The flexible action buttons move into the overflow menu when the
  // actions don't fit beside the owner. The width of the full row is
  // measured while it is shown, and compared with the room there is.
  const updateActionsLayout = () => {
    const row = rowRef.current;
    const owner = ownerRef.current;
    const actions = actionsRef.current;
    if (!row || !owner || !actions) return;
    if (!compactActions) fullActionsWidth.current = actions.scrollWidth;
    setCompactActions(fullActionsWidth.current > row.clientWidth - owner.offsetWidth);
  };
  useResizeObserver(rowRef, updateActionsLayout);
  const menu = primaryInfo?.videoActions?.menuRenderer as MenuRenderer | undefined;
  const owner = secondaryInfo?.owner?.videoOwnerRenderer as VideoOwnerRenderer | undefined;
  const subscribe = secondaryInfo?.subscribeButton?.subscribeButtonRenderer as SubscribeButtonRenderer | undefined;
  const rows = secondaryInfo?.metadataRowContainer?.metadataRowContainerRenderer as MetadataRowContainerRenderer | undefined;
  return (
    <div ref={ref} className={styles.metadata}>
      <div className={styles.aboveTheFold}>
        <div className={styles.titleRow}>
          <div className={styles.title}>
            <h1 className={styles.heading}>
              <FormattedString text={primaryInfo?.title as FormattedText | undefined} />
            </h1>
          </div>
        </div>
        <div ref={rowRef} className={styles.topRow}>
          <div ref={ownerRef} id="owner" className={styles.owner}>
            {owner && <VideoOwner data={owner} />}
            {subscribe && (
              <div className={styles.subscribeButton}>
                <SubscribeButton data={subscribe} />
              </div>
            )}
          </div>
          <div className={styles.actions}>
            <div ref={actionsRef} className={styles.actionsInner}>
              {menu && <Menu data={menu} showFlexibleItems={!compactActions} className={styles.actionsMenu} />}
            </div>
          </div>
        </div>
        <div className={styles.bottomRow}>
          {/* The whole box expands the description; links and buttons inside it keep their own action. */}
          <div
            className={clsx(styles.description, !expanded && styles.collapsed)}
            onClick={(e) => {
              if (!expanded && !(e.target as Element).closest("a, button")) setExpanded(true);
            }}
          >
            <div className={styles.descriptionInner}>
              {primaryInfo && <WatchInfoText data={primaryInfo} />}
              <TextInlineExpander
                text={secondaryInfo?.attributedDescription as AttributedText | undefined}
                collapsedLines={secondaryInfo?.descriptionCollapsedLines}
                description={page.structuredDescription}
                expanded={expanded}
                onExpandedChange={setExpanded}
                moreText={secondaryInfo?.showMoreText as FormattedText | undefined}
                lessText={secondaryInfo?.showLessText as FormattedText | undefined}
              />
            </div>
            <TouchFeedback className={styles.descriptionFeedback} />
          </div>
        </div>
      </div>
      {rows && <MetadataRowContainer data={rows} />}
    </div>
  );
}
