import { useRef, useState } from "react";
import type { CommentRepliesRenderer, CommentThreadRenderer } from "../../model/innertube.gen";
import { useImpression } from "../../logging/impressions";
import { CommentViewModel } from "./CommentViewModel";
import { CommentReplies } from "./CommentReplies";
import styles from "./CommentThread.module.css";

/** A comment and the entry point to its replies. */
export function CommentThread({ data, videoId }: { data: CommentThreadRenderer; videoId: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const [expanded, setExpanded] = useState(false);
  const viewModel = data.commentViewModel.commentViewModel;
  const replies = data.replies?.commentRepliesRenderer as CommentRepliesRenderer | undefined;
  return (
    <div ref={ref} className={styles.thread} data-renderer="commentThreadRenderer">
      <div className={styles.commentContainer}>{viewModel && <CommentViewModel data={viewModel} videoId={videoId} hasThreadline={!!replies} />}</div>
      {replies && (
        <div className={styles.replies}>
          <CommentReplies data={replies} expanded={expanded} onExpandedChange={setExpanded} />
        </div>
      )}
      {replies && (
        // The thread line beside the replies toggles them too; the replies
        // button is the accessible control.
        <button type="button" className={styles.hitbox} tabIndex={-1} aria-hidden="true" onClick={() => setExpanded(!expanded)} />
      )}
    </div>
  );
}
