import { useId } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { Endpoint } from "../../model/endpoints";
import type { CommentEntity, CommentSharedEntity, ToolbarStateEntity, ToolbarSurfaceEntity } from "../../model/comments";
import { setEntity, useEntity } from "../../state/entities";
import { logClick } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { ButtonShape } from "../../components/button/ButtonShape";
import { Tooltip } from "../../components/feedback/Tooltip";
import { Icon } from "../../components/icon/Icon";
import styles from "./CommentEngagementBar.module.css";

const messages = defineMessages({
  reply: { id: "comment.reply", defaultMessage: "Reply" },
});

type LikeState = NonNullable<ToolbarStateEntity["likeState"]>;
const LIKED: LikeState = "TOOLBAR_LIKE_STATE_LIKED";
const DISLIKED: LikeState = "TOOLBAR_LIKE_STATE_DISLIKED";
const INDIFFERENT: LikeState = "TOOLBAR_LIKE_STATE_INDIFFERENT";

interface ToggleProps {
  icon: string;
  pressed: boolean;
  label: string | undefined;
  tooltip: string | undefined;
  onToggle: () => void;
}

function ToolbarToggle({ icon, pressed, label, tooltip, onToggle }: ToggleProps) {
  const tooltipId = useId();
  return (
    <div className={styles.toggle}>
      <ButtonShape icon={icon} size="s" pressed={pressed} label={label || undefined} describedBy={tooltip ? tooltipId : undefined} onClick={onToggle} />
      <Tooltip text={tooltip ?? ""} id={tooltipId} />
    </div>
  );
}

export interface CommentEngagementBarProps {
  comment: CommentEntity;
  shared: CommentSharedEntity | undefined;
  toolbarStateKey: string | undefined;
  surface: ToolbarSurfaceEntity | undefined;
  isReply: boolean;
}

/**
 * The like and dislike toggles with the like count, the creator's heart
 * and the reply button. The like state is an entity. Signed out, the
 * buttons ask the user to sign in instead of changing it.
 */
export function CommentEngagementBar({ comment, shared, toolbarStateKey, surface, isReply }: CommentEngagementBarProps) {
  const intl = useIntl();
  const runCommand = useRunCommand();
  const replyTooltipId = useId();
  const state = useEntity<ToolbarStateEntity>(toolbarStateKey);
  const likeState = state?.likeState ?? INDIFFERENT;
  const toolbar = comment.toolbar ?? {};
  const toolbarShared = shared?.toolbarShared ?? {};
  const likeCount = (likeState === LIKED ? toolbar.likeCountLiked : toolbar.likeCountNotliked)?.trim();
  const signIn = surface?.prepareAccountCommand?.innertubeCommand;
  const toggle = (target: LikeState, on: Endpoint | undefined, off: Endpoint | undefined) => {
    logClick(comment.loggingDirectives);
    if (signIn) {
      runCommand(signIn);
      return;
    }
    const active = likeState === target;
    if (toolbarStateKey) setEntity(toolbarStateKey, { ...state, likeState: active ? INDIFFERENT : target });
    runCommand(active ? off : on);
  };
  const replyText = shared?.strings?.replyButtonText || intl.formatMessage(messages.reply);
  return (
    <div className={styles.bar}>
      <div className={styles.toolbar}>
        <ToolbarToggle
          icon="LIKE"
          pressed={likeState === LIKED}
          label={likeState === LIKED ? toolbarShared.unlikeButtonA11y : toolbar.likeButtonA11y}
          tooltip={likeState === LIKED ? toolbar.likeActiveTooltip : toolbar.likeInactiveTooltip}
          onToggle={() => toggle(LIKED, surface?.likeCommand?.innertubeCommand, surface?.unlikeCommand?.innertubeCommand)}
        />
        {likeCount && likeCount !== "0" && (
          <span className={styles.voteCount} aria-label={toolbar.likeCountA11y}>
            {likeCount}
          </span>
        )}
        <ToolbarToggle
          icon="DISLIKE"
          pressed={likeState === DISLIKED}
          label={likeState === DISLIKED ? toolbarShared.undislikeButtonA11y : isReply ? toolbarShared.dislikeReplyButtonA11y : toolbarShared.dislikeCommentButtonA11y}
          tooltip={likeState === DISLIKED ? toolbar.dislikeActiveTooltip : toolbar.dislikeInactiveTooltip}
          onToggle={() => toggle(DISLIKED, surface?.dislikeCommand?.innertubeCommand, surface?.undislikeCommand?.innertubeCommand)}
        />
        {state?.heartState === "TOOLBAR_HEART_STATE_HEARTED" && (
          <div className={styles.creatorHeart} title={toolbar.heartActiveTooltip}>
            <Icon icon="FAVORITE" size={16} label={toolbarShared.heartButtonA11y} />
          </div>
        )}
        <div className={styles.reply}>
          <ButtonShape
            text={replyText}
            size="s"
            label={toolbarShared.replyButtonA11y || replyText}
            describedBy={replyTooltipId}
            onClick={() => runCommand(signIn ?? surface?.replyCommand?.innertubeCommand)}
          />
          <Tooltip text={replyText} id={replyTooltipId} />
        </div>
      </div>
    </div>
  );
}
