import { useRef } from "react";
import type { CommentSimpleboxRenderer, CommentsHeaderRenderer, SortFilterSubMenuRenderer } from "../../model/innertube.gen";
import type { FormattedText } from "../../model/text";
import { useImpression } from "../../logging/impressions";
import { FormattedString } from "../../components/text/FormattedString";
import type { Endpoint } from "../../model/endpoints";
import { SortFilterSubMenu } from "../../components/menu/SortFilterSubMenu";
import { CommentSimplebox } from "./CommentSimplebox";
import styles from "./CommentsHeader.module.css";

export interface CommentsHeaderProps {
  data: CommentsHeaderRenderer;
  /** Reloads the comments sorted another way, with the sort option's continuation. */
  onSort: (continuation: Endpoint) => void;
}

/** The comment count, the sort menu and the box to write a comment. */
export function CommentsHeader({ data, onSort }: CommentsHeaderProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const sortMenu = data.sortMenu?.sortFilterSubMenuRenderer as SortFilterSubMenuRenderer | undefined;
  const simplebox = (data.createRenderer as { commentSimpleboxRenderer?: CommentSimpleboxRenderer } | undefined)?.commentSimpleboxRenderer;
  return (
    <div ref={ref} className={styles.header}>
      {data.countText && (
        <div className={styles.title}>
          <div className={styles.leadingSection}>
            <h2 className={styles.count}>
              <FormattedString text={data.countText as FormattedText} />
            </h2>
          </div>
          <div className={styles.additionalSection}>{sortMenu && <SortFilterSubMenu data={sortMenu} onSelect={onSort} />}</div>
        </div>
      )}
      {simplebox && (
        <div className={styles.simpleBox}>
          <CommentSimplebox data={simplebox} />
        </div>
      )}
    </div>
  );
}
