import { infiniteQueryOptions, queryOptions } from "@tanstack/react-query";
import { continuation, getWatch } from "../../api/innertube";
import { parseResponse } from "../../model/response";
import type { Endpoint } from "../../model/endpoints";
import type { RelatedAppendResponse } from "../../model/innertube.gen";
import { relatedPageFromAppend, watchPageFromResponse, type RelatedPage } from "../../model/watch";
import { continuationParam, measured, type PageParam } from "../../api/requests";

export const NEXT_API = "/youtubei/v1/next";

export function watchQueryOptions(videoId: string, endpoint: Endpoint | undefined) {
  // The endpoint adds only player params and click tracking to the
  // request; the video is the same page however it was reached.
  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  return queryOptions({
    queryKey: ["watch", videoId],
    // Without a page to show, the route's error element replaces it. A
    // failed background refetch keeps the cached page.
    throwOnError: (_error, query) => query.state.data === undefined,
    queryFn: () =>
      measured("watch", "navigation", async () =>
        watchPageFromResponse(
          await getWatch({ videoId, playerParams: endpoint?.watchEndpoint?.playerParams, clickTrackingParams: endpoint?.clickTrackingParams }),
          videoId,
        ),
      ),
  });
}

/**
 * The related list: the first page comes with the watch response, later
 * pages are continuations. Only continuations are fetched, so the query
 * never goes stale on its own.
 */
export function relatedQueryOptions(videoId: string, first: RelatedPage) {
  // The first page comes from the watch response, which the video id identifies.
  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  return infiniteQueryOptions({
    queryKey: ["related", videoId],
    initialPageParam: null as PageParam | null,
    initialData: { pages: [first], pageParams: [null] },
    staleTime: Infinity,
    queryFn: async ({ pageParam }): Promise<RelatedPage> => {
      if (!pageParam) return first;
      return measured("watch", "continuation", async () =>
        relatedPageFromAppend(parseResponse<RelatedAppendResponse>(await continuation("related-append", NEXT_API, pageParam.token, pageParam.clickTrackingParams))),
      );
    },
    getNextPageParam: (last) => continuationParam(last.continuation),
  });
}
