import { useEffect, useId, useRef, useState } from "react";
import type { SortFilterSubMenuRenderer } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { accessibilityLabel } from "../../model/text";
import { logClick } from "../../logging/impressions";
import { Icon } from "../icon/Icon";
import { Tooltip } from "../feedback/Tooltip";
import styles from "./SortFilterSubMenu.module.css";

interface SubMenuItem {
  title?: string;
  subtitle?: string;
  selected?: boolean;
  serviceEndpoint?: Endpoint;
  trackingParams?: string;
}

export interface SortFilterSubMenuProps {
  data: SortFilterSubMenuRenderer;
  /** Called with the continuation command that loads the list sorted the chosen way. */
  onSelect?: (continuation: Endpoint) => void;
}

/** A "Sort by" button that opens the list of sort orders. */
export function SortFilterSubMenu({ data, onSelect }: SortFilterSubMenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const tooltipId = useId();
  const listId = useId();
  const [open, setOpen] = useState(false);
  const items = (data.subMenuItems ?? []) as SubMenuItem[];
  const label = data.title ?? "";
  useEffect(() => {
    if (!open) return;
    const close = (e: PointerEvent) => {
      if (!ref.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open]);
  const close = () => {
    setOpen(false);
    triggerRef.current?.focus();
  };
  const choose = (item: SubMenuItem) => {
    close();
    if (item.selected) return;
    logClick(item);
    if (item.serviceEndpoint && onSelect) onSelect(item.serviceEndpoint);
  };
  return (
    <div ref={ref} className={styles.sortMenu} onKeyDown={(e) => e.key === "Escape" && open && close()}>
      <button
        ref={triggerRef}
        type="button"
        className={styles.trigger}
        aria-label={accessibilityLabel(data.accessibility as { accessibilityData?: { label?: string } }) || label}
        aria-describedby={data.tooltip ? tooltipId : undefined}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listId : undefined}
        onClick={() => setOpen(!open)}
      >
        <Icon icon={data.icon?.iconType ?? "SORT"} className={styles.icon} />
        <div className={styles.label}>{label}</div>
      </button>
      {data.tooltip && <Tooltip text={data.tooltip} id={tooltipId} />}
      {open && (
        <div id={listId} className={styles.dropdown} role="listbox" aria-label={label}>
          {items.map((item, i) => (
            <button key={i} type="button" role="option" aria-selected={!!item.selected} className={styles.item} onClick={() => choose(item)}>
              <span className={styles.itemTitle}>{item.title}</span>
              {item.subtitle && <span className={styles.itemSubtitle}>{item.subtitle}</span>}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
