import { useRef, useState, type CSSProperties } from "react";
import type { WatchPage } from "../../model/watch";
import { useMediaQuery } from "../../hooks/useMediaQuery";
import { useResizeObserver } from "../../hooks/useResizeObserver";
import { useWindowHeight, useWindowWidth } from "../../hooks/useWindowSize";
import { Player } from "../player/Player";
import { CommentsSection } from "../comments/CommentsSection";
import { WatchMetadata } from "./metadata/WatchMetadata";
import { EngagementPanels } from "./panels/EngagementPanels";
import { RelatedList } from "./related/RelatedList";
import { PlayerAds } from "./related/PlayerAds";
import styles from "./WatchFlexy.module.css";

const MASTHEAD_HEIGHT = 56;
/** Space below the player that the default layout keeps for the title row. */
const SPACE_BELOW_PLAYER = 48;
const TOP_PADDING = 12;
const SIDEBAR_WIDTH_RATIO = 0.275;
const SIDEBAR_MIN_WIDTH = 320;
const SIDEBAR_MAX_WIDTH = 402;
const COMPACT_THUMBNAIL_WIDTH = "55%";
/** The panels' height bound in the one-column layout. */
const ONE_COLUMN_PANEL_MAX_HEIGHT = 460;

interface Size {
  width: number;
  height: number;
}

/**
 * The layout of a watch page for a window size: the sidebar width, the
 * page margin, and the player size that the window allows, which also
 * bounds the panels' height.
 */
function watchLayout(windowWidth: number, windowHeight: number, twoColumns: boolean) {
  const margin = windowWidth >= 1600 ? 24 : 16;
  const sidebar = Math.min(SIDEBAR_MAX_WIDTH, Math.max(SIDEBAR_MIN_WIDTH, windowWidth * SIDEBAR_WIDTH_RATIO));
  const maxWidth = Math.floor(((windowHeight - MASTHEAD_HEIGHT - TOP_PADDING - SPACE_BELOW_PLAYER) * 16) / 9);
  const playerWidth = Math.max(0, Math.min(windowWidth - sidebar - 3 * margin, maxWidth));
  const panelMaxHeight = twoColumns ? Math.round((playerWidth * 9) / 16) : ONE_COLUMN_PANEL_MAX_HEIGHT;
  return {
    "--yt-watch-flexy-space-below-player": `${SPACE_BELOW_PLAYER}px`,
    "--yt-watch-flexy-horizontal-page-margin": `${margin}px`,
    "--yt-watch-flexy-top-padding": `${TOP_PADDING}px`,
    "--yt-watch-flexy-sidebar-width": `${sidebar}px`,
    "--yt-watch-compact-thumbnail-width": COMPACT_THUMBNAIL_WIDTH,
    "--yt-watch-flexy-panel-max-height": `${panelMaxHeight}px`,
  } as CSSProperties;
}

/**
 * The watch page layout: the player and the content below it in the
 * primary column, the engagement panels and the related list in the
 * secondary column. Narrow windows get one column, with the related list
 * above the comments.
 */
export function WatchFlexy({ page }: { page: WatchPage | undefined }) {
  const twoColumns = useMediaQuery("(min-width: 1017px)");
  const windowWidth = useWindowWidth();
  const windowHeight = useWindowHeight();
  const outerRef = useRef<HTMLDivElement>(null);
  const [playerSize, setPlayerSize] = useState<Size>({ width: 0, height: 0 });
  const measurePlayer = () => {
    const container = outerRef.current;
    if (!container) return;
    const width = container.clientWidth;
    const height = Math.round((width * 9) / 16);
    setPlayerSize((size) => (size.width === width && size.height === height ? size : { width, height }));
  };
  useResizeObserver(outerRef, measurePlayer);

  const related = page && (
    <div id="related" className={styles.related}>
      <PlayerAds ads={page.playerAds} />
      <RelatedList videoId={page.videoId} section={page.relatedSection} first={page.related} oneColumn={!twoColumns} />
    </div>
  );
  return (
    <div className={styles.flexy} data-page="watch" data-two-columns={twoColumns || undefined} style={watchLayout(windowWidth, windowHeight, twoColumns)}>
      <div className={styles.columns}>
        <div className={styles.primary}>
          <div className={styles.primaryInner}>
            <div id="player" className={styles.player}>
              <div className={styles.cinematicsContainer}>
                <div className={styles.cinematics} />
              </div>
              <div ref={outerRef} className={styles.playerContainerOuter}>
                <div className={styles.playerContainerInner}>
                  <div className={styles.playerContainer}>
                    {page && <Player response={page.player} width={playerSize.width} height={playerSize.height} />}
                  </div>
                </div>
              </div>
            </div>
            <div className={styles.below}>
              {page && <WatchMetadata page={page} />}
              {!twoColumns && related}
              {page?.comments && <CommentsSection videoId={page.videoId} section={page.comments} />}
            </div>
          </div>
        </div>
        <div className={styles.secondary}>
          <div className={styles.secondaryInner}>
            {page && <EngagementPanels panels={page.panels} />}
            {twoColumns && related}
          </div>
        </div>
      </div>
    </div>
  );
}
