import { useRef } from "react";
import type { MetadataRowContainerRenderer } from "../../../model/innertube.gen";
import { useImpression } from "../../../logging/impressions";
import styles from "./MetadataRowContainer.module.css";

/**
 * The container for rows of video metadata (music, game, licence). The
 * responses in this workload have no rows, only the container's logging.
 */
export function MetadataRowContainer({ data }: { data: MetadataRowContainerRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return <div ref={ref} className={styles.container} />;
}
