import type {
  ContinuationItemRenderer,
  EngagementPanelSectionListRenderer,
  ItemSectionRenderer,
  PlayerLegacyDesktopWatchAdsRenderer,
  RelatedAppendResponse,
  StructuredDescriptionContentRenderer,
  VideoPrimaryInfoRenderer,
  VideoSecondaryInfoRenderer,
  WatchNextResponse,
  WatchPlayerResponse,
} from "./innertube.gen";
import { processResponse, type Processed, type ResponseBase } from "./response";

// The watch page model. The get_watch request answers with two parts, the
// player response and the watch-next response, which the page turns into
// the player data, the metadata below the player, the engagement panels,
// the comment section's first continuation and the first page of the
// related list.

export type PlayerResponse = WatchPlayerResponse["playerResponse"];
type WatchNext = WatchNextResponse["watchNextResponse"];

/** An item of the related list: a lockup, or the continuation at its end. */
export type RelatedItem = { lockupViewModel?: object; continuationItemRenderer?: ContinuationItemRenderer } & Record<string, unknown>;

export interface RelatedPage {
  items: RelatedItem[];
  continuation: ContinuationItemRenderer | null;
}

export interface WatchPage {
  videoId: string;
  title: string;
  player: PlayerResponse;
  primaryInfo: VideoPrimaryInfoRenderer | null;
  secondaryInfo: VideoSecondaryInfoRenderer | null;
  /** The comment section before its first load: a continuation item. */
  comments: ItemSectionRenderer | null;
  panels: EngagementPanelSectionListRenderer[];
  /** The full description, which the description panel shows and the inline description expands to. */
  structuredDescription: StructuredDescriptionContentRenderer | null;
  related: RelatedPage;
  relatedSection: ItemSectionRenderer | null;
  playerAds: PlayerLegacyDesktopWatchAdsRenderer[];
}

const DESCRIPTION_PANEL = "engagement-panel-structured-description";

function splitContinuation(items: RelatedItem[]): RelatedPage {
  const last = items.at(-1);
  if (last?.continuationItemRenderer) return { items: items.slice(0, -1), continuation: last.continuationItemRenderer };
  return { items, continuation: null };
}

/** Turns the two parts of a get_watch response into the page model. */
export function watchPageFromResponse(text: string, videoId: string): WatchPage {
  const parts = JSON.parse(text) as Array<WatchPlayerResponse | WatchNextResponse>;
  let player: PlayerResponse | undefined;
  let next: WatchNext | undefined;
  for (const part of parts) {
    if ("playerResponse" in part) player = part.playerResponse;
    else if ("watchNextResponse" in part) next = part.watchNextResponse;
  }
  if (!player || !next) throw new Error("incomplete get_watch response");
  processResponse(player as unknown as ResponseBase);
  processResponse(next as WatchNext & ResponseBase);
  const results = next.contents.twoColumnWatchNextResults;
  let primaryInfo: VideoPrimaryInfoRenderer | null = null;
  let secondaryInfo: VideoSecondaryInfoRenderer | null = null;
  let comments: ItemSectionRenderer | null = null;
  for (const item of results.results.results.contents) {
    if (item.videoPrimaryInfoRenderer) primaryInfo = item.videoPrimaryInfoRenderer;
    else if (item.videoSecondaryInfoRenderer) secondaryInfo = item.videoSecondaryInfoRenderer;
    else if (item.itemSectionRenderer?.sectionIdentifier === "comment-item-section") comments = item.itemSectionRenderer;
  }
  const panels = (next.engagementPanels ?? []).flatMap((p) => (p.engagementPanelSectionListRenderer ? [p.engagementPanelSectionListRenderer] : []));
  const descriptionPanel = panels.find((p) => p.panelIdentifier === DESCRIPTION_PANEL);
  const relatedSection = results.secondaryResults?.secondaryResults.results.find((r) => r.itemSectionRenderer)?.itemSectionRenderer ?? null;
  const title = player.videoDetails?.title ?? "";
  return {
    videoId: player.videoDetails?.videoId ?? videoId,
    title,
    player,
    primaryInfo,
    secondaryInfo,
    comments,
    panels,
    structuredDescription: (descriptionPanel?.content?.structuredDescriptionContentRenderer as StructuredDescriptionContentRenderer | undefined) ?? null,
    related: splitContinuation((relatedSection?.contents ?? []) as RelatedItem[]),
    relatedSection,
    playerAds: (player.playerAds ?? []).flatMap((a) => (a.playerLegacyDesktopWatchAdsRenderer ? [a.playerLegacyDesktopWatchAdsRenderer] : [])),
  };
}

/** The lockups that a related-list continuation appends. */
export function relatedPageFromAppend({ commands }: Processed<RelatedAppendResponse>): RelatedPage {
  const items: RelatedItem[] = [];
  for (const c of commands) {
    const append = c.appendContinuationItemsAction as { targetId?: string; continuationItems?: RelatedItem[] } | undefined;
    if (append?.targetId === "watch-next-feed") items.push(...(append.continuationItems ?? []));
  }
  return splitContinuation(items);
}
